import * as THREE from 'three';
export function createWorldAudio(camera){
 let context=null,buffers=null,phase=null,lastFoot=0,echo=null,reloadSource=null,accentCount=0;const active=new Set(),forward=new THREE.Vector3(),up=new THREE.Vector3();
 async function unlock(){try{context??=new (window.AudioContext||window.webkitAudioContext)();await context.resume();if(!echo){echo=context.createDelay(.3);echo.delayTime.value=.11;const gain=context.createGain(),filter=context.createBiquadFilter();gain.gain.value=.12;filter.type='lowpass';filter.frequency.value=1700;echo.connect(filter).connect(gain).connect(context.destination);}buffers??=Promise.all(['gunshot.mp3','step-left.wav','step-right.wav','reload.mp3','rocket-explosion.mp3','katana-swing.mp3'].map(async name=>context.decodeAudioData(await(await fetch(new URL('./audio/'+name,import.meta.url))).arrayBuffer())));await buffers;}catch{buffers=null;}}
 addEventListener('pointerdown',unlock,{passive:true});addEventListener('keydown',unlock,{passive:true});
 async function play(index,volume=1,position=null,state=null){if(!context||context.state!=='running'||!buffers||volume<=0)return;try{const samples=await buffers;if(active.size>=12){const oldest=active.values().next().value;oldest.stop();active.delete(oldest);}const source=context.createBufferSource(),gain=context.createGain(),filter=context.createBiquadFilter();source.buffer=samples[index];gain.gain.value=volume*(index===4?1:index===0?.65:.3);filter.type='lowpass';let distance=0,panner=null;if(position){const point=new THREE.Vector3(position.x,position.y,position.z);distance=camera.position.distanceTo(point);const blocked=state.world?.cameraPosition(camera.position,point,.015).distanceTo(point)>.25;filter.frequency.value=index===4?Math.max(4000,18000-distance*65):blocked?850:Math.max(2200,14000-distance*90);gain.gain.value*=blocked?(index===4?.8:.3):1;panner=context.createPanner();panner.panningModel='HRTF';panner.distanceModel='inverse';panner.refDistance=index===4?24:6;panner.maxDistance=index===4?320:180;panner.rolloffFactor=index===4?.8:1.1;panner.setPosition(point.x,point.y,point.z);}else filter.frequency.value=14000;
 source.connect(filter).connect(gain);if(panner){gain.connect(panner);panner.connect(context.destination);if(index===0||index===4)panner.connect(echo);}else{gain.connect(context.destination);if(index===0||index===4)gain.connect(echo);}active.add(source);source.onended=()=>{active.delete(source);source.disconnect();filter.disconnect();gain.disconnect();panner?.disconnect();};source.start(context.currentTime+Math.min(.65,distance/343));}catch{}}
 function accent(kind){if(kind==='finish'||kind==='reload')return;if(!context||context.state!=='running'||accentCount>=8)return;const now=context.currentTime,duration=kind==='finish'?.6:kind==='reload'?.09:.18,osc=context.createOscillator(),gain=context.createGain();accentCount++;osc.type=kind==='finish'?'triangle':'sine';osc.frequency.setValueAtTime(kind==='finish'?420:kind==='reload'?900:kind==='shot'?120:75,now);osc.frequency.exponentialRampToValueAtTime(kind==='finish'?840:kind==='reload'?220:35,now+duration);gain.gain.setValueAtTime(.0001,now);gain.gain.linearRampToValueAtTime(kind==='finish'?.065:kind==='reload'?.045:.09,now+.006);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain).connect(context.destination);osc.onended=()=>{accentCount--;osc.disconnect();gain.disconnect();};osc.start();osc.stop(now+duration+.02);}
 return {accent,cancelReload(){reloadSource?.stop();reloadSource=null;},async reload(duration=3250){await unlock();if(!context||!buffers)return;const samples=await buffers;await new Promise(resolve=>{const source=context.createBufferSource(),gain=context.createGain();reloadSource=source;source.buffer=samples[3];source.playbackRate.value=Math.max(.25,Math.min(4,samples[3].duration/(duration/1000)));gain.gain.value=.75;source.connect(gain).connect(context.destination);source.onended=()=>{if(reloadSource===source)reloadSource=null;source.disconnect();gain.disconnect();resolve();};source.start();});},sword(position,state){play(5,1.2,position,state);},shot(position,state){play(0,1,position,state);},explosion(position,state){play(4,1,position,state);},update(state){if(context){const listener=context.listener;camera.getWorldDirection(forward);up.set(0,1,0).applyQuaternion(camera.quaternion);listener.setPosition(camera.position.x,camera.position.y,camera.position.z);listener.setOrientation(forward.x,forward.y,forward.z,up.x,up.y,up.z);}const a=state.avatar?.animation;if(!a||!state.inStudio||state.paused||state.seated||state.ragdoll||!a.grounded||a.speed<.3){phase=null;return;}const half=Math.floor(((a.phase+Math.PI/2)%(Math.PI*2))/Math.PI);if(phase!==null&&phase!==half&&state.now-lastFoot>130){play(half+1,state.prone?.15:1);lastFoot=state.now;}phase=half;}};
}
